        require(target != address(0));
        require(target.code.length == 0);
        require(address(this).balance >= 0);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        c.sendMoney(target, 0, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
